    11	/**
    12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    14	 * (half-even) at every step.
    15	 */
    16	public final class PriceCalculator {
    17	
    18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
    19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    20	
    21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    22	        int nights = 0;
    23	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    24	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    25	            subtotal = subtotal.add(nightPrice(room, night));
    26	            nights++;
    27	        }
    28	        BigDecimal discount = switch (ratePlan) {
    29	            case STANDARD -> cents(BigDecimal.ZERO);
    30	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    31	        };
    32	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    33	    }
