    39	        }
    40	        return cents(nightlyRate);
    41	    }
    42	
    43	    /**
    44	     * High season: from December 15 to the end of February, the whole of July, and Holy Week (Palm
    45	     * Sunday to Easter Sunday, both included) in the years listed. A new season, or a new year of
    46	     * Easter, is one more entry here.
    47	     */
    48	    private static final List<Predicate<LocalDate>> HIGH_SEASONS = List.of(
    49	            date -> date.getMonth() == Month.JANUARY || date.getMonth() == Month.FEBRUARY,
    50	            date -> date.getMonth() == Month.DECEMBER && date.getDayOfMonth() >= 15,
    51	            date -> date.getMonth() == Month.JULY,
    52	            between(LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 28)),
    53	            between(LocalDate.of(2028, 4, 9), LocalDate.of(2028, 4, 16)));
    54	
    55	    static boolean isHighSeason(LocalDate date) {
    56	        return HIGH_SEASONS.stream().anyMatch(season -> season.test(date));
    57	    }
    58	
    59	    private static Predicate<LocalDate> between(LocalDate first, LocalDate last) {
    60	        return date -> !date.isBefore(first) && !date.isAfter(last);
    61	    }
